CREATE TABLE IF NOT EXISTS launch_turns (id UUID PRIMARY KEY, idea_id UUID NOT NULL REFERENCES launch_ideas(id), user_id UUID NOT NULL, prompt TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('initial','followup')), status TEXT NOT NULL CHECK (status IN ('queued','tracking','writing','complete','failed')), research_notes JSONB, recommendation JSONB, error_message TEXT, task_card_id UUID, task_url TEXT, deck_status TEXT NOT NULL DEFAULT 'none' CHECK (deck_status IN ('none','creating','ready','failed')), deck_path TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
